import java.util.*;
import java.io.*;
import java.nio.charset.StandardCharsets;
public class PropertiesSelection {
 public static void main(String[] args) throws Exception {
  for(boolean present:List.of(false,true)) {
   Properties original=new Properties();
   original.setProperty("attempt", "attempt-1");
   original.setProperty("argument.0", "line one\nline two\t<>&\"é");
   if(present) original.setProperty("environment.TOKEN", "");
   ByteArrayOutputStream output=new ByteArrayOutputStream();
   original.storeToXML(output,"Supervisor configuration",StandardCharsets.UTF_8);
   Properties received=new Properties();received.loadFromXML(new ByteArrayInputStream(output.toByteArray()));
   if(received.containsKey("environment.TOKEN")!=present || !original.equals(received)) throw new AssertionError(received);
   System.out.println("present="+present+" received_present="+received.containsKey("environment.TOKEN")+" value="+Objects.toString(received.getProperty("environment.TOKEN"),"<missing>")+" exact_roundtrip="+original.equals(received)+" attempt="+received.getProperty("attempt"));
   byte[] truncated=Arrays.copyOf(output.toByteArray(),output.size()/2);
   try {new Properties().loadFromXML(new ByteArrayInputStream(truncated));throw new AssertionError("Incomplete configuration accepted");}
   catch(InvalidPropertiesFormatException expected) {System.out.println("truncated_rejected="+expected.getClass().getSimpleName());}
  }
 }
}
